from __future__ import annotations
from typing import Any
import numpy as np
from physics_decoder import reconstruct_load
def evaluate(pred_x:np.ndarray,points:np.ndarray,q:np.ndarray,data:dict[str,Any],thr:dict[str,np.ndarray],sl:slice=slice(9,20))->dict[str,float]:
    px=pred_x[:,sl];tx=data["truth_x"][:,sl];n=data["norms"];ep=px-tx;state={"state_core":float(np.sqrt(np.mean(ep[...,:30]**2))),"connector_disp":float(np.sqrt(np.mean(ep[...,30:38]**2))),"connector_vel":float(np.sqrt(np.mean(ep[...,38:46]**2))),"state_all":float(np.sqrt(np.mean(ep**2)))};tp=data["truth_points"][:,sl];tq=data["truth_q"][:,sl];pn=(points[:,sl].reshape(len(px),len(range(*sl.indices(20))),8)-n["force_mean"][:8])/n["force_std"][:8];tn=data["truth_f"][:,sl,:8];qn=(q[:,sl]-n["force_mean"][8:10])/n["force_std"][8:10];tqn=data["truth_f"][:,sl,8:10];force=float(np.sqrt(np.mean((pn-tn)**2)));load=float(np.sqrt(np.mean((qn-tqn)**2)));pf=points[:,sl].reshape(len(px),-1,8);tf=tp.reshape(len(px),-1,8);cm=np.abs(tf)>=thr["component_floor"].reshape(1,1,8);component=float(np.mean(np.sign(pf[cm])==np.sign(tf[cm])));qm=np.abs(tq)>=thr["q_floor"].reshape(1,1,2);qacc=float(np.mean(np.sign(q[:,sl][qm])==np.sign(tq[qm])));pm=np.linalg.norm(tp,axis=-1)>=thr["point_floor"].reshape(1,1,4);pnorm=np.linalg.norm(points[:,sl],axis=-1);cos=np.sum(points[:,sl]*tp,axis=-1)/np.maximum(pnorm*np.linalg.norm(tp,axis=-1),1e-12);angles=np.degrees(np.arccos(np.clip(cos,-1,1)))[pm&(pnorm>1e-12)];allp=points.reshape(len(points),20,8);allt=data["truth_points"].reshape(len(points),20,8);active=np.abs(allt)>=thr["component_floor"].reshape(1,1,8);events=active[:,1:]&active[:,:-1]&(np.sign(allt[:,1:])!=np.sign(allt[:,:-1]));mask=np.zeros_like(active)
    for b,h,c in np.argwhere(events):mask[b,max(0,h+1-10):min(20,h+2+10),c]=True
    mask&=active;rev=float(np.mean(np.sign(allp[mask])==np.sign(allt[mask])));div=float(np.mean(np.any(~np.isfinite(np.c_[px.reshape(len(px),-1),points[:,sl].reshape(len(px),-1)]),axis=1)));return {**state,"force":force,"load":load,"J":(state["state_all"]+force+load)/3,"component_accuracy":component,"Q_accuracy":qacc,"angle_mae_deg":float(np.mean(angles)),"angle_p95_deg":float(np.quantile(angles,.95)),"reversal_accuracy":rev,"reversal_events":int(np.sum(events)),"Q_residual_N":float(np.max(np.abs(reconstruct_load(points)-q))),"divergence_rate":div}
